import re
out={k:T.get(i,k) for i,k in enumerate(keys)}
ph=lambda s:sorted(re.findall(r'\{\d+\}',s))
tags=lambda s:re.findall(r'<[^>]+>',s)
for k,v in out.items():
    assert ph(k)==ph(v),(k,v)
    assert tags(k)==tags(v),(k,v)
json.dump(out,open('ui_es_1.json','w'),ensure_ascii=False,indent=1)
d=json.load(open('ui_es_1.json'));assert set(d)==set(keys) and len(d)==len(keys)
print(len(d), sum(1 for k in d if d[k]==k))
